exercises.solution:
List<Artikel> liste = new List<Artikel>();
bool laeuft = true;

while (laeuft)
{
    switch (Console.ReadLine())
    {
        case "1":
            string name = Console.ReadLine();
            int menge = int.Parse(Console.ReadLine());
            Artikel vorhanden = Suche(liste, name);
            if (vorhanden != null)
            {
                vorhanden.Menge += menge;
                Console.WriteLine($"{name}: jetzt {vorhanden.Menge}");
            }
            else
            {
                liste.Add(new Artikel { Name = name, Menge = menge });
                Console.WriteLine($"{menge}x {name} hinzugefügt.");
            }
            break;
        case "2":
            foreach (Artikel a in liste)
                Console.WriteLine($"{a.Name} ({a.Menge})");
            break;
        case "0":
            Console.WriteLine("Tschüss!");
            laeuft = false;
            break;
    }
}

static Artikel Suche(List<Artikel> liste, string name)
{
    foreach (Artikel a in liste)
        if (a.Name == name) return a;
    return null;
}

class Artikel
{
    public string Name { get; set; }
    public int Menge { get; set; }
}
